  "Chat width": "רוחב הצ'אט",
  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "שוחח עם מודל לבחירתך; {mnemo} קורא, כותב, מתייג, מקשר, מעביר ומסדר הערות בכלים של Memora עצמה. הוא לא יכול לגלוש באינטרנט, להריץ פקודות, למחוק לצמיתות או לשנות את השרת. המפתחות חתומים בשרת הזה ולעולם לא נשלחים לדפדפן.",
  "Chat with your notes agent": "שוחח עם סוכן ההערות שלך",
  "ChatGPT only signs in over OAuth; it cannot send a key header.": "ChatGPT מתחבר רק דרך OAuth; הוא לא יכול לשלוח כותרת מפתח.",
