  "Checklist steps tick right on the card with a click or a tap, saved with history and live on every screen.": "שלבי רשימת המשימות מסומנים ישירות על הכרטיס בלחיצה או בהקשה, נשמרים עם היסטוריה ומופיעים בזמן אמת בכל מסך.",
