  "Choose between 0.1 and 50 MB": "בחר בין 0.1 ל-50 MB",
  "Choose from many languages in Settings, Appearance, per device. Auto follows your browser.": "בחר מבין שפות רבות בהגדרות, מראה, לכל מכשיר. אוטומטי עוקב אחרי הדפדפן שלך.",
  "Choose your vault folder": "בחר את תיקיית הכספת שלך",
  "Chosen colour": "הצבע שנבחר",
  "Chosen when it signs in": "נבחר בעת ההתחברות",
  "Claude Desktop (older)": "Claude Desktop (ישן)",
  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude ו-ChatGPT מתחברים עם חשבון Memora שלך. אין מה להעתיק.",
  "Claude models": "מודלים של Claude",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude מתחבר דרך OAuth, ולכן לא מדביקים מפתח: הוא מקבל מפתח משלו כשאתה לוחץ על אפשר. בלי התחברות, חבר אותו כ<b>אפליקציה אחרת</b> ושלח את הכותרת <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor ועוד",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor ועוד, כל אחד עם מפתח משלו",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex ואחרים מקבלים כל אחד גישה משלו, כך שאפשר לראות מה כל אחד עושה.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT והסוכן שלך חולקים Memora אחת, שאפשר להגיע אליה מהמחשב הזה, מהרשת המקומית או מהאינטרנט",
  "Claude, Cursor, ChatGPT and your own scripts read your notes and add to them.": "Claude, Cursor, ChatGPT והסקריפטים שלכם קוראים את ההערות שלכם ומוסיפים להן.",
