  "Click <b>Add</b>, then <b>Connect</b>. A Memora page opens: sign in if asked and press <b>Allow</b>.": "לחץ על <b>הוסף</b>, ואז על <b>התחבר</b>. נפתח דף של Memora: התחבר אם תתבקש ולחץ על <b>אפשר</b>.",
  "Click a card or tab to it first.": "לחץ קודם על כרטיס או עבור אליו עם Tab.",
  "Click or tick tags to see their notes. Need more, like {example}? Use {button}": "לחץ או סמן תגיות כדי לראות את ההערות שלהן. צריך עוד, כמו {example}? השתמש ב-{button}",
