  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "גרור כרטיס למסגרת של תיקייה אחרת כדי להעביר את ההערה בדיסק. גרור מסגרת לפי שמה כדי לסדר את הלוח מחדש; שחרר אותה על מסגרת אחרת כדי להעביר לשם את כל התיקייה. לחץ פעמיים על כותרת לשינוי שם. במגע: גרור להזזה, צבוט להתקרבות, לחיצה ארוכה על כרטיס כדי להזיז אותו, הקשה לתצוגה מקדימה.",
  "Drag a note here to pin it": "גרור הערה לכאן כדי לנעוץ אותה",
  "Drag notes or folders here to pin them": "גרור הערות או תיקיות לכאן כדי לנעוץ אותן",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "גרור הערות או תיקיות אל תיקייה כדי להעביר אותן, או אל נעוצים כדי לנעוץ אותן.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "גרור הערות · לחיצה כפולה לנעיצה · / חיפוש · #tag מוצא תגיות · F התאמה · 1 2 3 פריסות",
  "Drag to move the folder frame; double-click to rename": "גרור כדי להזיז את מסגרת התיקייה; לחץ פעמיים לשינוי שם",
  "Drag to move the lane. Double click the name to rename it.": "גרור כדי להזיז את העמודה. לחץ לחיצה כפולה על השם כדי לשנות אותו.",
  "Drag to resize · double-click to reset": "גרור לשינוי גודל · לחץ פעמיים לאיפוס",
