  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "גרור לסיבוב · גלול לזום · לחץ על נקודה כדי לפתוח את ההערה שלה · / לחיפוש · #tag מוצא תגיות",
