  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "כל אפליקציית AI שאתה מחבר היא סוכן עם מפתח משלו, כך שאפשר לראות מה כל אחת עושה ולכבות אחת בנפרד.",
