  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "כל סוכן שייך לאפליקציה אחת. כדי להשתמש ב-Memora באפליקציה אחרת, צור לה סוכן נפרד.",
  "Each app gets its own key": "כל אפליקציה מקבלת מפתח משלה",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "לכל אחד מזהה קצר שלא משתנה לעולם, כך שאפשר לשנות שמות בחופשיות. Mnemo מקים אותם, משנה הנחיות או מודל, שולח להם הודעות, מחכה להם, עוצר, מסיים ומסיר אותם, אחד אחד או כולם יחד, ויכול לתת להם לעבוד ברקע. כל כרטיס מציג הנחיה, פעילות ותשובה.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "כל סוג נמדד מול המרחב שלו: המגבלה שלו אם הוגדרה, אחרת מה שהוא משתמש בו ועוד שטח הדיסק הפנוי{disk}. מגבלה ריקה: ללא.",
  "Each one gets its own key from Memora.": "כל אחד מקבל מפתח משלו מ-Memora.",
