  "Embed new or existing boards in a note and work on each right there, or put a board into any note from its ⋯ menu; a plain link reads as a small card.": "הטמע לוחות חדשים או קיימים בהערה ועבוד על כל אחד מהם במקום, או הכנס לוח לכל הערה מתפריט ⋯ שלה; קישור רגיל מוצג ככרטיס קטן.",
