  "Error": "שגיאה",
  "Error 404": "שגיאה 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "גם בשימוש יומיומי, דפדפן מתחבר שוב אחרי זמן כזה. הוא לא יכול להיות קצר מזמן חוסר הפעילות.",
  "Every AI loses {n} tool at once. Asks first.": "כל ה-AI מאבדים {n} כלי בבת אחת. שואל קודם.",
  "Every AI loses {n} tools at once. Asks first.": "כל ה-AI מאבדים {n} כלים בבת אחת. שואל קודם.",
  "Every Kanban board in your notes": "כל לוחות הקנבן שבהערות שלך",
  "Every action, newest first": "כל פעולה, החדשה ביותר ראשונה",
  "Every action, newest first, with search and filters.": "כל פעולה, החדשה ביותר ראשונה, עם חיפוש ומסננים.",
  "Every address from one to another.": "כל כתובת מאחת לאחרת.",
  "Every address from the first to the last, joined by a dash.": "כל כתובת מהראשונה ועד האחרונה, מחוברות במקף.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "סוכנים בדרך כלל מתחילים מאפס. {bold} חבר כל סוכן פעם אחת וכולם יקראו את אותה כספת ויכתבו אליה בחזרה, כך שמה שאחד לומד, האחרים יכולים להשתמש בו.",
  "Every archived card is back on the board": "כל הכרטיסים שבארכיון חזרו ללוח",
  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "כל לוח עם העמודות וההתקדמות שלו. “לוח חדש” נמצא בכל מקום שבו נמצא “הערה חדשה”: סרגל הצד, סקירה, תיקיות, תפריטים, חיפוש ומקש B.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "כל דפדפן וסוכן מנותקים עד שמישהו יפעיל את Memora שוב במכונה הזו. הדף הזה לא יכול להפעיל אותה שוב.",
  "Every call shows up live in the brain and Activity": "כל קריאה מופיעה בשידור חי במוח ובפעילות",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "כל שינוי ש-Mnemo עושה מופיע בפעילות ואפשר לבטל אותו מהיסטוריה.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "כל שינוי, שלך או של אפליקציה, מופיע בפעילות ואפשר לבטל אותו מהיסטוריה.",
  "Every chat is archived.": "כל הצ'אטים בארכיון.",
  "Every chat with your notes agent": "כל צ'אט עם סוכן ההערות שלך",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "כל ה-AI המחוברים מאבדים את כל {n} הכלים בבת אחת ולא יכולים עוד לקרוא או לשנות את ההערות שלך עד שתפעיל כלים שוב כאן.",
  "Every connected AI loses it at once. You can turn it back on any time.": "כל ה-AI המחוברים מאבדים אותו בבת אחת. אפשר להפעיל אותו שוב בכל עת.",
  "Every connected AI loses them at once. You can turn them back on any time.": "כל ה-AI המחוברים מאבדים אותם בבת אחת. אפשר להפעיל אותם שוב בכל עת.",
  "Every connected agent loses its memory until Memora runs again.": "כל סוכן מחובר מאבד את הזיכרון שלו עד ש-Memora תרוץ שוב.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "כל מכשיר ברשת ביתית או משרדית, בכתיבה כתובת/גודל: ‏192.168.1.0/24 מכסה את 192.168.1.0 עד 192.168.1.255.",
  "Every device on a home or office network.": "כל מכשיר ברשת ביתית או משרדית.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "כל תמונה בתיקיית ההערות ואיפה היא מוצגת, והתמונות ששמורות לצ'אטים של Mnemo.",
  "Every image is used in a note.": "כל תמונה בשימוש בהערה.",
  "Every note": "כל הערה",
  "Every note and link, in 3D, as a graph or on a board.": "כל הערה וקישור, בתלת-ממד, כגרף או על לוח.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "כל ההערות ותתי-התיקיות ב-\"{path}\" עוברות אל {folder}; אחר כך \"{name}\" מוסרת. אם שם כבר תפוס שם, מתווסף אליו מספר.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "כל הערה הופכת כאן לכרטיס, בתוך מסגרת של התיקייה שלה. המדריך מראה איך לגרום ל-AI לשמור כאן את הידע שלו, או לכתוב הערה בעצמך.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "כל הערה הופכת כאן לנקודת אור, מקובצת לפי תיקייה. המדריך מראה איך לגרום ל-AI לשמור כאן את הידע שלו, או לכתוב הערה בעצמך.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "כל הערה מתויגת #{tag} ({notes}) מקבלת את השם החדש, וגם תגיות #inline בטקסט.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "כל הערה מתויגת {tags} מקבלת תגית אחת במקומן ({notes}). גם תגיות #inline בטקסט משתנות. אין ביטול בשלב אחד; לכל הערה יש היסטוריה משלה.",
  "Every read and write by an agent shows up live, so you always know who did what.": "כל קריאה וכתיבה של סוכן מופיעות בשידור חי, כך שתמיד תדע מי עשה מה.",
  "Every request that reaches this rule is {verb}.": "כל בקשה שמגיעה לכלל הזה היא {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "כל בקשה. שים אותו אחרון כדי לתפוס מה שהכללים שמעליו לא תפסו.",
  "Every setting and where it lives.": "כל הגדרה ואיפה היא נמצאת.",
  "Every shortcut in the web UI.": "כל קיצור במשק האינטרנט.",
  "Every tag and its notes": "כל תגית וההערות שלה",
  "Every tool agents can call": "כל כלי שסוכנים יכולים לקרוא לו",
