  "From now on, whenever I tell you something important, save it into Memora. Try it now: save a note that I started using Memora today.": "מעכשיו, בכל פעם שאגיד לך משהו חשוב, שמור אותו ב-Memora. נסה עכשיו: שמור הערה שהתחלתי להשתמש ב-Memora היום.",
