  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "אוסף את הפעילות האמיתית עבור {range}. ביומן גדול זה עשוי לקחת רגע, אנא המתן.",
  "General": "כללי",
  "Get a one-time code on the server": "קבל קוד חד-פעמי בשרת",
  "Get started": "בוא נתחיל",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "הכירו אותי דרך ההערות שלי. עבור על הכספת שלי (הערות אחרונות, יומנים, פרויקטים, כל מה שקשור אליי) ושמור את מה שלמדת עם remember_owner: מי אני, על מה אני עובד, איך אני אוהב לקבל תשובות, מה אני אוהב. רק דברים קצרים ובני קיימא, אף פעם לא סודות. אחר כך ספר לי בכמה שורות מה שמרת.",
  "Gets its own agent key: read and write nodes over MCP": "מקבל מפתח סוכן משלו: קריאה וכתיבה של צמתים דרך MCP",
  "Getting started": "תחילת העבודה",
  "GitHub answered HTTP {code}": "GitHub ענה HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "תן ל-Claude, ל-Cursor או לכל אפליקציית MCP מפתח משלה, ואז תן לה לשמור את מה שהיא כבר יודעת עליך.",
  "Give a key read-only access, or let it write too.": "תן למפתח גישה לקריאה בלבד, או אפשר לו גם לכתוב.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "תן לכל אפליקציה או מכשיר סוכן משלו. אז פעילות תראה בדיוק מי עשה מה, ואפשר לכבות אחד בלי לגעת באחרים.",
  "Give it a name you recognise": "תן לו שם שתזהה",
