  "How Memora looks for you. Saved in this browser only.": "איך Memora נראית בשבילך. נשמר בדפדפן הזה בלבד.",
  "How far apart the folder islands of the Clusters layout are.": "כמה רחוקים אי התיקיות בפריסת צבירים.",
