  "How it works": "איך זה עובד",
  "How large an image may be, and what images take": "מה גודל התמונה המותר, ומה תמונות תופסות",
  "How many notes": "כמה הערות",
  "How much history the server keeps": "כמה היסטוריה השרת שומר",
  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "כמה מקום תופסים הערות, תמונות וצ'אטים של Mnemo, כל אחד מול המרחב שלו. באנר מזהיר כשאחד כמעט מלא.",
  "How the agent itself shows up: its display name and colour.": "איך הסוכן עצמו מופיע: שם התצוגה והצבע שלו.",
  "How to update": "איך לעדכן",
  "How {mnemo} works": "איך {mnemo} עובד",
  "Humanist": "הומניסטי",
  "Hyphenate long words": "פיצול מילים ארוכות במקף",
  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "אני מוצא, קורא, כותב, מתייג, מקשר ומסדר את ההערות שלך. בלי אינטרנט, בלי shell: רק הכספת שלך.",
  "Icon": "סמל",
  "Icon {name}": "סמל {name}",
  "Ideas grow when they connect. Link this note to {a} or read {b}.": "רעיונות צומחים כשהם מתחברים. קשר את ההערה הזו אל {a} או קרא {b}.",
  "Identity": "זהות",
  "Idle": "במנוחה",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "אם זה עזר לך, כוכב ב-GitHub או סיפור לחבר עוזרים לאחרים למצוא את זה. אין בעיה אם לא.",
  "If you leave, they are kept on this device and offered again when you open the note.": "אם תעזוב, הם יישמרו במכשיר הזה ויוצעו שוב כשתפתח את ההערה.",
  "Image": "תמונה",
  "Image (or paste or drop one)": "תמונה (או הדבק או שחרר אחת)",
  "Image deleted": "התמונה נמחקה",
