  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora בודקת את התיקייה ומבקשת ממך לאשר לפני שהיא עוברת. שום דבר לא מועבר או מועתק, ואפשר לחזור לכאן. רץ ב-Docker? השתמש בתיקייה שמוטענת לתוך המכולה.",
  "Memora could not start.": "Memora לא הצליחה להתחיל.",
  "Memora data folder": "תיקיית הנתונים של Memora",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora בודקת קודם שהתיקייה החדשה קיימת (או שאפשר ליצור אותה) ושהיא יכולה לשמור שם הערות. אם הבדיקה נכשלת, שום דבר לא משתנה.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora בודקת קודם שהתיקייה החדשה קיימת ושהיא יכולה לשמור שם הערות. אם הבדיקה נכשלת, שום דבר לא משתנה.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora בשפה שלך, Mnemo שמציג את התוכנית שלו תוך כדי עבודה, ואתה בוחר במה מותר לו להשתמש ומה לראות.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora היא אפליקציית הערות שגם אפליקציות ה-AI שלך יכולות להשתמש בה. אתה כותב בה, הן קוראות וכותבות את אותן הערות, ואתה תמיד יכול לראות מה השתנה.",
  "Memora is free and open source": "Memora חינמית ובקוד פתוח",
  "Memora is free and open source. A star helps others find it.": "Memora חינמית ובקוד פתוח. כוכב עוזר לאחרים למצוא אותה.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora היא זיכרון, מתקדם: נבנתה לזכור מה שאתה וה-AI שלך לומדים, ולזכור יותר ככל שמשתמשים בה יותר.",
  "Memora is restarting": "Memora מופעלת מחדש",
  "Memora is shut down": "Memora כבויה",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora עדיין ריקה. חבר אפליקציית AI, שלח לה הנחיה אחת, והיא תשמור כאן מה שהיא יודעת עליך, כהערות שאפשר לקרוא, לערוך ולראות במוח.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora שומרת רשימה של התגיות שלך כדי להציע אותן בזמן ההקלדה. רענן אותה אם תגית חסרה או לא מעודכנת.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora שומרת כל גרסה של הערה כשתיקיית הכספת היא מאגר git. הרץ {cmd} בתיקיית הכספת פעם אחת (ראה תצורה, “היסטוריית גרסאות” בתיעוד); מאותו רגע כל שינוי נשמר כאן.",
  "Memora keeps it in one place:": "Memora שומרת את זה במקום אחד:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora שומרת כל הערה כקובץ Markdown פשוט במכונה שהיא רצה עליה. שום דבר לא נעול: פתח את הקבצים בכל עורך, גבה אותם, או שמור אותם ב-Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora מדברת MCP על גבי HTTP מזרים. אפליקציות שולחות את המפתח בכותרת <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora נעצרת במכונה שהיא רצה עליה. ההערות שלך נשארות בטוחות בדיסק.",
  "Memora version": "גרסת Memora",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} זמינה. השרת הזה מריץ v{current}.",
  "Memora v{version} is available": "Memora v{version} זמינה",
  "Memora, open Overview": "Memora, פתח סקירה",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: כספת הערות שאתה מארח בעצמך, עם סוכן שמסדר אותה.",
  "Memory used: {used} of {win}": "זיכרון בשימוש: {used} מתוך {win}",
  "Mentioned in": "מוזכר ב",
  "Mentions": "אזכורים",
  "Menus that fit": "תפריטים שמתאימים",
  "Menus that fit where you are, an archive you can search, softer progress and due dates, and steps you can tick on the card.": "תפריטים שמתאימים למקום שבו אתה נמצא, ארכיון שאפשר לחפש בו, התקדמות ותאריכי יעד רכים יותר, ושלבים שאפשר לסמן על הכרטיס.",
  "Menus, tidied": "תפריטים מסודרים",
  "Merge": "מזג",
  "Merge into": "מזג אל",
  "Merge {n} tags": "מזג {n} תגיות",
  "Merged": "מוזג",
