  "Merged notes": "הערות שמוזגו",
  "Merged tags": "תגיות שמוזגו",
  "Merged {tags} into #{into} · {notes} changed": "{tags} מוזגו אל #{into} · {notes} השתנו",
  "Merge…": "מזג…",
  "Merging tags… {n} of {total}": "ממזג תגיות… {n} מתוך {total}",
  "Mesh": "רשת",
  "Message": "הודעה",
  "Message copied": "ההודעה הועתקה",
  "Message to {mnemo}": "הודעה אל {mnemo}",
  "Messaged {agent}": "הודעה ל-{agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "ההודעות ותיבת ההודעה מיושרות בדיוק בכל רוחב, לבורר המודל יש משטח משלו, הצ׳אט החולף מתאים לטלפון, ואפשרויות השאלה לא זזות כשמקישים עליהן.",
  "Middle-drag": "גרירה באמצע",
  "Midnight": "חצות",
  "Minimap": "מיני-מפה",
  "Minimap: click or drag to move the view": "מיני-מפה: לחץ או גרור כדי להזיז את התצוגה",
  "Mist": "ערפל",
  "Mnemo (AI agent)": "Mnemo (סוכן AI)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Mnemo וסוכנים יכולים לעשות בלוח כל מה שאתה יכול, דרך MCP, מאחורי ארבעה מתגי הרשאות של קנבן שפועלים לפי שאל קודם, אוטומטי וקריאה בלבד.",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "כפתור Mnemo הוסתר. הצג אותו שוב מ\"עוד\", הצג את כפתור Mnemo.",
  "Mnemo goes on without sub-agents": "Mnemo ממשיך בלי תת-סוכנים",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "ל-Mnemo אין עדיין מודל: הוסף ספק ואת המודלים שלו בהגדרות, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo מובנה ב-Memora. חבר מפתח AI משלך ואז שאל במילים פשוטות: הוא מוצא, כותב, מתייג, מקשר ומסדר הערות בשבילך.",
  "Mnemo is still answering in this chat": "Mnemo עדיין עונה בצ'אט הזה",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo הוא הסוכן המובנה ב-Memora. חברו מפתח AI משלכם ובקשו במילים פשוטות: הוא שומר על הסדר בהערות שלכם בזמן שהאפליקציות האחרות משתמשות בהן.",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo שומר לכל היותר {n} ספקים; מחק אחד קודם",
  "Mnemo knows what is due": "Mnemo יודע מה מגיע ליעדו",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo מנהל את סוכני המשנה שלו, שומר את התוכנית עם הצ׳אט, והצ׳אט מתאים טוב יותר לכל מסך.",
  "Mnemo runs its sub-agents": "Mnemo מנהל את סוכני המשנה שלו",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo עצר אחרי {n} שלבים; כתוב \"המשך\" כדי להמשיך.",
  "Mnemo's plan, live": "התוכנית של Mnemo, בשידור חי",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "השאלה של Mnemo מופיעה ברצועה משלה, והתשובות מתחתיה כשורות להקשה, כמה שהשאלה צריכה.",
  "Mnemo, your notes agent": "Mnemo, סוכן ההערות שלך",
