  "More: rename, move, colour, delete": "עוד: שינוי שם, העברה, צבע, מחיקה",
  "More: rename, move, pin, delete": "עוד: שינוי שם, העברה, נעיצה, מחיקה",
  "Most AI apps start each chat from nothing, and each keeps its own memory. With Memora, Claude, Cursor and any other app that speaks MCP read and write the same notes, so what one app learns, the others can use.": "רוב אפליקציות ה-AI מתחילות כל צ'אט מאפס, וכל אחת שומרת זיכרון משלה. עם Memora, Claude, Cursor וכל אפליקציה אחרת שמדברת MCP קוראות וכותבות את אותן הערות, כך שמה שאפליקציה אחת לומדת, האחרות יכולות להשתמש בו.",
  "Most cards in this lane (0 for no limit)": "מספר הכרטיסים המרבי בעמודה זו (0 ללא מגבלה)",
