  "Move the folder \"{name}\" with its {n} notes into \"{target}\"? The notes move on disk to {path}.": "להעביר את התיקייה \"{name}\" עם {n} ההערות שלה אל \"{target}\"? ההערות עוברות בדיסק אל {path}.",
