  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "לא בוצע: Mnemo במצב שאל קודם, ולכן שינויים ממתינים לאישור הבעלים. שאל עם ask_owner (אמור מה תשנה; תן אפשרות עם approve: true כמו \"כן, המשך\"), ואז בצע את השינוי אחרי שהם יאשרו.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "לא בוצע: Mnemo במצב קריאה בלבד, ולכן הערות לא משתנות. אמור מה היית משנה; הבעלים יכול לעבור ל\"שאל קודם\" או ל\"אוטומטי\" בצ'אט.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "לא בוצע: הצ'אט במצב שאל קודם, ולכן תת-סוכן לא יכול לשנות הערות. אמור בתשובה שלך מה צריך להשתנות; Mnemo ישאל את הבעלים.",
