  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "הערות ולוחות חולקים מסגרת עמוד אחת עם אותם מרווחים בטלפון, בטאבלט ובמחשב, והקישורים בתחתית ההערה מקבלים מראה אחיד ומסודר שאפשר לקפל.",
  "Notes and boards, connected": "הערות ולוחות, מחוברים",
  "Notes and images in the notes folder.": "הערות ותמונות בתיקיית ההערות.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "הערות והקישורים ביניהן מופיעים כאן כמפה. המדריך מראה איך לגרום ל-AI לשמור כאן את הידע שלו, או לכתוב הערה בעצמך.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "הערות מופיעות כשה-AI שומר אותן ומאירות את המוח. הדף הזה הופך ללוח הבקרה שלך כשההערה הראשונה מגיעה.",
  "Notes are not a password manager.": "הערות הן לא מנהל סיסמאות.",
