  "Notes from {name}": "הערות מאת {name}",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "הערות בפורמט Obsidian Kanban נפתחות כלוחות. גרור כרטיסים ועמודות בעכבר או באצבע, וכל שינוי נרשם בהיסטוריה של ההערה.",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "הערות בתיקייה הנוכחית לא מועברות, לא מועתקות ולא נמחקות. אפשר לחזור לכאן בכל עת.",
