  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "עדיין לא הוסתר דבר: סמן את הסוכנים שמהם להסתיר. כרגע הסוכן היחיד יכול לראות אותו.",
  "Nothing in 24h": "שום דבר ב-24 שעות",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "שום דבר בשמות הערות, בתיקיות או בטקסט, ושום דבר שנכתב קרוב לזה. נסה פחות אותיות, איות אחר, או מילה מתוך הערה.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "שום דבר ב-24 השעות האחרונות. מה שה-AI שלך עושים מופיע כאן כשזה קורה.",
  "Nothing in the log goes by “{name}”. Showing all activity.": "שום דבר ביומן לא נושא את השם “{name}”. מציג את כל הפעילות.",
  "Nothing in this range": "שום דבר בטווח הזה",
  "Nothing in your chats says “{query}”.": "שום דבר בצ'אטים שלך לא אומר “{query}”.",
  "Nothing is allowed. Turn something on, or pause the agent instead.": "שום דבר לא מותר. הפעל משהו, או השהה את הסוכן במקום.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "שום דבר לא אבד: הטקסט הנוכחי נשאר בהיסטוריה כ-v{n}, כך שאפשר לחזור בכל עת.",
  "Nothing links here yet.": "עדיין שום דבר לא מקשר לכאן.",
  "Nothing matches": "אין התאמות",
  "Nothing matches with these filters.": "אין התאמות עם המסננים האלה.",
  "Nothing matches “{q}” with these filters.": "אין התאמות ל-“{q}” עם המסננים האלה.",
  "Nothing matches “{q}”.": "אין התאמות ל-“{q}”.",
  "Nothing matches “{q}”. Maybe you meant one of these:": "אין התאמות ל-“{q}”. אולי התכוונת לאחד מאלה:",
  "Nothing matches.": "אין התאמות.",
  "Nothing needs you right now.": "שום דבר לא דורש אותך כרגע.",
  "Nothing overdue": "אין איחורים",
  "Nothing recorded from this device yet.": "עדיין לא נרשם דבר מהמכשיר הזה.",
  "Nothing said here is kept.": "שום דבר שנאמר כאן לא נשמר.",
  "Nothing to compact yet": "עדיין אין מה לכווץ",
