  "Nothing to undo: “{title}” is not pinned already.": "אין מה לבטל: “{title}” עדיין לא נעוצה.",
  "Nothing to undo: “{title}” is pinned already.": "אין מה לבטל: “{title}” כבר נעוצה.",
