  "Only this note uses these settings.": "רק ההערה הזו משתמשת בהגדרות האלה.",
  "Only {names} can see this {what}. Every other agent, including ones added later, is blocked.": "רק {names} יכולים לראות את ה{what} הזה. כל סוכן אחר, כולל כאלה שיתווספו בהמשך, חסום.",
  "Only {name}": "רק {name}",
