  "Optional. A few words on who you are, what you work on, how you like answers. {mnemo} keeps them and you can change them any time in Settings.": "אופציונלי. כמה מילים על מי אתה, על מה אתה עובד, איך אתה אוהב תשובות. {mnemo} שומר אותן ואפשר לשנות אותן בכל עת בהגדרות.",
