  "Passwords match": "הסיסמאות תואמות",
  "Past activity keeps the old name; new activity uses this one.": "פעילות קודמת שומרת את השם הישן; פעילות חדשה משתמשת בזה.",
  "Past due dates show in a warning tint and today’s in a softer one, and the Boards page counts what is overdue. A board’s own date colours win.": "תאריכי יעד שחלפו מוצגים בגוון אזהרה והיום בגוון עדין יותר, ודף לוחות סופר מה שבאיחור. צבעי התאריכים של הלוח עצמו גוברים.",
  "Paste both into the app and save.": "הדבק את שניהם באפליקציה ושמור.",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "הדבק בטרמינל ולחץ על <kbd>Enter</kbd>, ואז הפעל את Codex באותו טרמינל.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "הדבק בטרמינל ולחץ על <kbd>Enter</kbd>. אחר כך הפעל את Claude Code, או הפעל אותו מחדש: Memora נטענת מעצמה.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "הדבק בטרמינל ולחץ על <kbd>Enter</kbd>. אחר כך הפעל את Gemini CLI, או הפעל אותו מחדש, והקלד <code>/mcp</code> כדי לראות את Memora.",
  "Paste it into the app where it asks for a key.": "הדבק באפליקציה במקום שבו היא מבקשת מפתח.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "הדבק בקובץ ושמור, ואז לחץ על <b>רענן</b>. Memora תופיע ברשימה.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "הדבק בקובץ, שמור, והפעל מחדש את Claude Desktop. הוא דורש Node.js במחשב הזה.",
  "Paste it into {app}": "הדבק ב-{app}",
