  "Paste these once where {app} reads its standing instructions, so it uses Memora in every conversation, not only when asked.": "הדבק את אלה פעם אחת במקום ש-{app} קורא את ההוראות הקבועות שלו, כך שישתמש ב-Memora בכל שיחה, לא רק כשמבקשים.",
