  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "שמור ב-Memora את מה ששיתפתי איתך על חיי האישיים: תחומי העניין, ההרגלים, המטרות, האנשים החשובים לי ודברים שאכפת לי מהם. שים את ההערות האלה בתיקייה בשם Private, הערה אחת לכל נושא, וקשר הערות קשורות. לעולם אל תשמור סיסמאות, מספרי כרטיסים או סודות אחרים. כשתסיים, ספר לי מה שמרת.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "שמור ב-Memora את מה שאתה יודע על העבודה שלי: התפקיד שלי, הצוות שלי, הפרויקטים שאני בהם ואיפה הם עומדים, וההחלטות שקיבלנו. צור הערה אחת לכל פרויקט או נושא וקשר ביניהן.",
