  "Tint": "גוון",
  "Title": "כותרת",
  "To": "עד",
  "To do": "לביצוע",
  "To start it again, someone must run {cmd} (or start its service) on the machine it runs on. This page cannot start it.": "כדי להפעיל אותו שוב, מישהו צריך להריץ {cmd} (או להפעיל את השירות שלו) במכונה שהוא רץ עליה. הדף הזה לא יכול להפעיל אותו.",
  "To-dos, follow-ups, checks that a note is well formed, and the pinned notes and folders.": "מטלות, מעקבים, בדיקות שהערה בנויה היטב, וההערות והתיקיות הנעוצות.",
  "Today": "היום",
  "Together": "יחד",
  "Toggle sidebar": "הצג/הסתר סרגל צד",
