  "Too many attempts": "יותר מדי ניסיונות",
  "Too many failed attempts. Try again in 1 minute.": "יותר מדי ניסיונות כושלים. נסה שוב בעוד דקה.",
  "Too many failed attempts. Try again in {n} minutes.": "יותר מדי ניסיונות כושלים. נסה שוב בעוד {n} דקות.",
  "Too many requests. Slow down and try again shortly.": "יותר מדי בקשות. האט ונסה שוב בקרוב.",
  "Too many requests. Wait a few seconds and try again.": "יותר מדי בקשות. המתן כמה שניות ונסה שוב.",
  "Too many wrong codes, so this reset code no longer works. Run memora-cli reset-password on the server for a new one.": "יותר מדי קודים שגויים, ולכן קוד האיפוס הזה כבר לא עובד. הרץ memora-cli reset-password בשרת כדי לקבל חדש.",
  "Too many wrong codes, so this setup code no longer works. Run memora-cli setup on the server for a new one.": "יותר מדי קודים שגויים, ולכן קוד ההגדרה הזה כבר לא עובד. הרץ memora-cli setup בשרת כדי לקבל חדש.",
  "Tool": "כלי",
