  "Tools": "כלים",
  "Tools added later stay blocked for this agent.": "כלים שנוספו מאוחר יותר נשארים חסומים עבור הסוכן הזה.",
  "Tools run under the name {mnemo} so every action shows in Activity. Tap a tool to switch it off or on, for {mnemo} itself or for its sub-agents. A tool switched off on the Tools page is off for both. Saved at once.": "כלים רצים תחת השם {mnemo} כך שכל פעולה מופיעה בפעילות. הקש על כלי כדי להפעיל או לכבות אותו, עבור {mnemo} עצמו או עבור תתי-הסוכנים שלו. כלי שכבוי בדף הכלים כבוי לשניהם. נשמר מיד.",
  "Top": "למעלה",
  "Top level": "רמה עליונה",
  "Traced a path": "עקב אחר נתיב",
  "Transport, connecting clients, OAuth, results and errors.": "תעבורה, חיבור לקוחות, OAuth, תוצאות ושגיאות.",
  "Trash": "פח",
  "Trash a board or a note from the Boards page, the board itself or the note lists, then bring it back with Undo in the toast.": "העבירו לוח או פתק לפח מדף לוחות, מהלוח עצמו או מרשימות הפתקים, והחזירו אותו עם ביטול בהודעה.",
  "Trash and settings": "פח והגדרות",
