  "Turn on at least one thing it may do, or turn the agent off instead.": "הפעל לפחות דבר אחד שמותר לו לעשות, או כבה את הסוכן במקום.",
  "Turn on due date reminders in Settings: one notification when a card falls due and one a day for what is overdue. The Boards item counts what is late.": "הפעל תזכורות לתאריך יעד בהגדרות: התראה אחת כשכרטיס מגיע ליעדו ואחת ביום על מה שבאיחור. הפריט לוחות סופר מה שמאחר.",
  "Turn on only what the app needs. You can change this any time.": "הפעל רק את מה שהאפליקציה צריכה. אפשר לשנות את זה בכל עת.",
