  "You now have long-term memory through Memora. Save into Memora everything you know about me from our conversations: who I am, my work, the projects I'm on, my preferences and important decisions. Make one note per topic in a fitting folder, and link notes that belong together. When you're done, tell me what you saved.": "יש לך עכשיו זיכרון לטווח ארוך דרך Memora. שמור ב-Memora כל מה שאתה יודע עליי מהשיחות שלנו: מי אני, העבודה שלי, הפרויקטים שאני בהם, ההעדפות שלי והחלטות חשובות. צור הערה אחת לכל נושא בתיקייה מתאימה, וקשר הערות ששייכות יחד. כשתסיים, ספר לי מה שמרת.",
