  "{mnemo} asks this model when you want a picture made.": "{mnemo} פונה למודל הזה כשאתה רוצה שייווצר תמונה.",
  "{mnemo} button hidden. Bring it back from More, Show the {mnemo} button.": "כפתור {mnemo} הוסתר. החזר אותו מ\"עוד\", הצג את כפתור {mnemo}.",
  "{mnemo} button hidden. Show it again here or from More.": "כפתור {mnemo} הוסתר. הצג אותו שוב כאן או מ\"עוד\".",
  "{mnemo} could not write new ones just now. Check the model in Settings.": "{mnemo} לא הצליח לכתוב חדשות כרגע. בדוק את המודל בהגדרות.",
  "{mnemo} hands pictures to this model when the chat model cannot see.": "{mnemo} מעביר תמונות למודל הזה כשמודל הצ'אט לא יכול לראות.",
  "{mnemo} is working on this": "{mnemo} עובד על זה",
  "{mnemo} keeps only what you add": "{mnemo} שומר רק מה שאתה מוסיף",
