  "{mnemo} may learn about you": "{mnemo} רשאי ללמוד עליך",
  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} עובד רק בהערות שלך. כל שינוי מופיע בפעילות ואפשר לבטל אותו מהיסטוריה.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} קורא את הכספת שלך בצ'אט חדש ושומר כאן מה שהוא לומד.",
  "{mnemo} settings saved": "הגדרות {mnemo} נשמרו",
  "{mnemo} settings: models and keys": "הגדרות {mnemo}: מודלים ומפתחות",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} מפעיל תתי-סוכנים מעצמו כשמשימה מתפצלת היטב; אין מה להגדיר. הם רצים על מודל ברירת המחדל שלך, ואז על מודלי הגיבוי, אלא אם תציין מודל בצ'אט. עקוב אחריהם, והחלף את המודל שלהם, ב\"סוכנים\" בפינה הימנית העליונה של הצ'אט. הם משתמשים באסימונים משלהם, ולכן ב\"שאל קודם\" {mnemo} שואל ואומר בערך כמה; ב\"אוטומטי\" הם פשוט רצים. נשמר מיד.",
  "{mnemo} stopped it": "{mnemo} עצר אותו",
  "{mnemo} will keep that in mind": "{mnemo} יזכור את זה",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "{mnemo} כותב הצעות חדשות מההערות האחרונות שלך (שלך נשארות)",
  "{mnemo}'s own ({n})": "של {mnemo} עצמו ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "הערות של {mnemo} עצמו על איך לדבר איתך, נקראות בכל צ'אט. לחץ על אחת כדי לשנות אותה.",
  "{mnemo}, your notes agent": "{mnemo}, סוכן ההערות שלך",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} לא יכול להסתכל בתמונות; הוא קיבל את השמות שלהן במקום. הגדר בהגדרות מודל שקורא תמונות כדי שיראה אותן.",
  "{model} cannot look at images; the image model described them for it.": "{model} לא יכול להסתכל בתמונות; מודל התמונות תיאר אותן עבורו.",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} לא יכול לקרוא תמונות, ולכן הוא מקבל רק את השמות שלהן. הגדר מודל שקורא תמונות, או החלף את המודל של הצ'אט הזה.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} לא יכול לקרוא תמונות, ולכן הוא קיבל רק את השמות שלהן. הגדר מודל שקורא תמונות, או החלף את המודל של הצ'אט הזה.",
